// Valida pedido e monta SQL (dono sanitizado, periodo whitelist)
const body = items[0].json.body || items[0].json;
const dono = String(body.dono || '').replace(/[^0-9]/g, '');
const periodos = ['hoje','semana','mes','mes_passado','tudo'];
const periodo = periodos.includes(body.periodo) ? body.periodo : 'mes';
if (!dono) return [];

const hojeLocal = "(NOW() AT TIME ZONE d.timezone)::date";
let filtro;
if (periodo === 'hoje') filtro = `g0.data_gasto = ${hojeLocal}`;
else if (periodo === 'semana') filtro = `g0.data_gasto >= ${hojeLocal} - 6`;
else if (periodo === 'mes') filtro = `date_trunc('month', g0.data_gasto) = date_trunc('month', ${hojeLocal})`;
else if (periodo === 'mes_passado') filtro = `date_trunc('month', g0.data_gasto) = date_trunc('month', ${hojeLocal} - INTERVAL '1 month')`;
else filtro = 'TRUE';

const sql = `SELECT d.numero, d.nome, d.timezone, d.moeda,\n  (SELECT COALESCE(json_agg(json_build_object('id', g0.id, 'data', to_char(g0.data_gasto,'DD/MM/YYYY'), 'descricao', g0.descricao, 'categoria', COALESCE(g0.categoria,'outros'), 'forma', COALESCE(g0.forma_pagamento,''), 'valor', g0.valor, 'obs', COALESCE(g0.observacoes,'')) ORDER BY g0.data_gasto, g0.id), '[]'::json)\n   FROM giulia_gastos g0 WHERE g0.dono_numero = d.numero AND ${filtro}) AS gastos\nFROM giulia_donos d WHERE d.numero = '${dono}';`;

return [{ json: { dono, periodo, sql } }];

// Monta resumo texto + configs dos graficos (QuickChart) + meta da planilha
const req = $('Preparar Pedido').first().json;
const d = (items[0] && items[0].json) || {};
const labelPeriodo = ({hoje:'hoje', semana:'ultimos 7 dias', mes:'mes atual', mes_passado:'mes passado', tudo:'periodo completo'})[req.periodo] || 'mes atual';
if (!d.numero) return [{ json: { vazio: true, dono: req.dono, texto: 'Nao consegui gerar o relatorio agora. Me pede de novo em instantes?' } }];
const gastos = typeof d.gastos === 'string' ? JSON.parse(d.gastos) : (d.gastos || []);
const SYM = d.moeda === 'USD' ? '$' : 'R$';
function fmt(v){ const n = Number(v) || 0; return SYM + ' ' + n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }
if (!gastos.length) return [{ json: { vazio: true, dono: d.numero, texto: `Nenhum gasto registrado no periodo (${labelPeriodo}).` } }];

const total = gastos.reduce((s,g) => s + (Number(g.valor)||0), 0);
const porCat = {};
for (const g of gastos) porCat[g.categoria] = (porCat[g.categoria]||0) + (Number(g.valor)||0);
let cats = Object.entries(porCat).sort((a,b) => b[1]-a[1]);
if (cats.length > 8) { const resto = cats.slice(7).reduce((s,c)=>s+c[1],0); cats = cats.slice(0,7); cats.push(['outros', resto]); }
const porDia = {};
for (const g of gastos) { const dd = String(g.data).substring(0,5); porDia[dd] = (porDia[dd]||0) + (Number(g.valor)||0); }
const dias = Object.entries(porDia);

// paleta categorica validada (ordem fixa, CVD-safe)
const CORES = ['#2a78d6','#1baf7a','#eda100','#008300','#4a3aa7','#e34948','#e87ba4','#eb6834'];
const pct = v => total ? Math.round(v/total*100) : 0;
const chartCat = {
  type: 'doughnut',
  data: { labels: cats.map(([c,v]) => `${c} - ${fmt(v)} (${pct(v)}%)`),
          datasets: [{ data: cats.map(([c,v]) => Math.round(v*100)/100), backgroundColor: CORES.slice(0, cats.length), borderColor: '#ffffff', borderWidth: 2 }] },
  options: { title: { display: true, text: ['Gastos por categoria', 'Total: ' + fmt(total)], fontSize: 18, fontColor: '#0b0b0b' },
             legend: { position: 'right', labels: { fontSize: 13, fontColor: '#0b0b0b' } },
             plugins: { datalabels: { display: false } } }
};
const chartDia = dias.length > 1 ? {
  type: 'bar',
  data: { labels: dias.map(x => x[0]), datasets: [{ data: dias.map(x => Math.round(x[1]*100)/100), backgroundColor: '#2a78d6', maxBarThickness: 40 }] },
  options: { title: { display: true, text: `Gasto por dia (${SYM}) - ${labelPeriodo}`, fontSize: 18, fontColor: '#0b0b0b' },
             legend: { display: false },
             scales: { yAxes: [{ ticks: { beginAtZero: true, fontColor: '#52514e' }, gridLines: { color: '#eeeeee' } }], xAxes: [{ ticks: { fontColor: '#52514e' }, gridLines: { display: false } }] },
             plugins: { datalabels: { display: false } } }
} : null;
const qc = cfg => 'https://quickchart.io/chart?w=700&h=420&bkg=white&c=' + encodeURIComponent(JSON.stringify(cfg));

const maior = gastos.reduce((m,g) => (Number(g.valor)||0) > (Number(m.valor)||0) ? g : m, gastos[0]);
const linhasCat = cats.map(([c,v]) => `  ${c}: ${fmt(v)} (${pct(v)}%)`).join('\n');
const agoraLocal = new Date().toLocaleString('sv-SE', { timeZone: d.timezone || 'America/Sao_Paulo' });
const dataFmt = agoraLocal.substring(8,10) + '/' + agoraLocal.substring(5,7) + '/' + agoraLocal.substring(0,4);
const nLanc = gastos.length === 1 ? '1 lancamento' : gastos.length + ' lancamentos';
const texto = `*Relatorio de gastos - ${labelPeriodo}*\n_Gerado em ${dataFmt}_\n\n*Total: ${fmt(total)}* (${nLanc})\n\n*Por categoria:*\n${linhasCat}\n\n*Maior gasto:* ${maior.descricao} - ${fmt(maior.valor)}\n\nSegue os graficos e a planilha completa.`;
const docname = `gastos-${req.periodo}-${dataFmt.replace(/\//g,'-')}.xlsx`;

return [{ json: { vazio: false, dono: d.numero, moeda: d.moeda || 'BRL', texto, chart_cat_url: qc(chartCat), chart_dia_url: chartDia ? qc(chartDia) : '', docname, gastos, total } }];

// Um item por midia (graficos) pra enviar em sequencia
const meta = $('Montar Meta').first().json;
const out = [];
if (meta.chart_cat_url) out.push({ json: { number: meta.dono, file: meta.chart_cat_url, caption: 'Como se distribui por categoria' } });
if (meta.chart_dia_url) out.push({ json: { number: meta.dono, file: meta.chart_dia_url, caption: 'Evolucao dia a dia' } });
return out;

// Linhas da planilha XLSX (uma por gasto + linha TOTAL)
const meta = $('Montar Meta').first().json;
const rows = meta.gastos.map(g => ({ json: {
  'Data': g.data,
  'Descricao': g.descricao,
  'Categoria': g.categoria,
  'Forma de pagamento': g.forma || '',
  'Valor': Number(g.valor) || 0,
  'Moeda': meta.moeda,
  'Observacoes': g.obs || ''
}}));
rows.push({ json: { 'Data': '', 'Descricao': 'TOTAL', 'Categoria': '', 'Forma de pagamento': '', 'Valor': Math.round(meta.total*100)/100, 'Moeda': meta.moeda, 'Observacoes': '' } });
return rows;
